// Isolation test (OS-12) — construct SignatureGate with its declared inputs and nothing
// else, then exercise every public operation. (Generated by new-object.py, rewritten for
// strict TypeScript - MF-21.)
import { describe, expect, it } from "vitest";
import { isUnknown } from "../src/kernel/index.js";
import type { DigestPort } from "../src/ports/index.js";
import type { Currency, Unit } from "../src/catalog/index.js";
import type { CandidateProposal } from "../src/facts/index.js";
import { SignatureGate } from "../src/lineage/index.js";
import { factWorld, never } from "./support/fact-world.js";

const u = "u1" as Unit;
const [c0, c1] = ["c0", "c1"] as unknown as readonly [Currency, Currency];
const one: DigestPort = { digest: (b) => `one:${Array.from(b).join(",")}` };
const other: DigestPort = { digest: (b) => `other:${Array.from(b).join(",")}` };

/** A real proposal from a real commitment (R-41). */
function proposal(): CandidateProposal {
  const w = factWorld({ currencies: ["c0", "c1"], invalidations: never });
  const k0 = w.commitAt(u, c0);
  const h = w.record.noise();
  const context = w.draws.recordDraw(u, {}, h, "cond", h, "ENGINE");
  if (isUnknown(context)) throw new Error("setup: the draw was refused");
  return { context, unit: u, currency: c1, condition: "cond", seed: "s", from: k0 };
}

describe("SignatureGate in isolation", () => {
  it("refuses to construct when an input is missing", () => {
    expect(() => new SignatureGate({} as never)).toThrow();
  });

  it("refuses inputs that do not offer the operations it calls (OS-1, declared slots)", () => {
    expect(() => new SignatureGate({ digests: {} as never })).toThrow();
  });

  it("materialOf answers differently when digests differs", () => {
    const p = proposal();
    expect(new SignatureGate({ digests: one }).materialOf(p)).not.toEqual(new SignatureGate({ digests: other }).materialOf(p));
  });

  it("sign answers differently when digests differs", () => {
    const p = proposal();
    const material = new SignatureGate({ digests: one }).materialOf(p);
    expect(new SignatureGate({ digests: one }).sign(material)).not.toEqual(new SignatureGate({ digests: other }).sign(material));
  });

  it("check answers differently when digests differs", () => {
    const p = proposal();
    const gate = new SignatureGate({ digests: one });
    const signature = gate.sign(gate.materialOf(p));
    expect(gate.check(p, signature)).not.toEqual(new SignatureGate({ digests: other }).check(p, signature));
  });
});
